import { floatRepr } from "./json";
import { isDict, PyError, truthy, type PyValue } from "./value";
import tables from "./unicode-tables.json";

// String behaviour frozen to CPython's unicodedata 15.1 (spike 1c rule 7). Node's ICU is newer:
// toLowerCase differs from str.casefold on 352 code points, /\s/ from str.isspace on 6, and
// String.normalize('NFKC') maps 37 code points CPython treats as unassigned.
// unicode-tables.json is generated by docs/plans/2026-10-23-nextjs-vercel-migration/spike-1c/gen_expected.py.

type Ranges = [number, number][];
const T = tables as unknown as {
  unassigned: Ranges; nonprintable: Ranges; space: Ranges; casefold: Record<string, string>; lower: Record<string, string>;
  case_ignorable: Ranges; cased: Ranges; decimal: [number, number, number][]; digit: Ranges; upper_ascii: Record<string, string>;
  word: Ranges; ignorecase_ascii: Record<string, number[]>;
};

const CASEFOLD = new Map(Object.entries(T.casefold).map(([k, v]) => [Number(k), v]));
const LOWER = new Map(Object.entries(T.lower).map(([k, v]) => [Number(k), v]));
const SPACE = new Set<number>(T.space.flatMap(([a, b]) => Array.from({ length: b - a + 1 }, (_, i) => a + i)));

function inRanges(r: Ranges, cp: number): boolean {
  let lo = 0, hi = r.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (cp < r[mid][0]) hi = mid - 1;
    else if (cp > r[mid][1]) lo = mid + 1;
    else return true;
  }
  return false;
}
const isUnassigned = (cp: number) => inRanges(T.unassigned, cp);
const isPrintable = (cp: number) => !inRanges(T.nonprintable, cp);

/** Code points the way CPython sees a str: a lone surrogate is one code point. */
export function codePoints(s: string): number[] {
  const out: number[] = [];
  for (let i = 0; i < s.length; i++) {
    const cp = s.codePointAt(i)!;
    out.push(cp);
    if (cp > 0xffff) i++;
  }
  return out;
}
const fromCps = (cps: number[]) => cps.map((c) => String.fromCodePoint(c)).join("");

/** len(s) */
export const pyLen = (s: string) => codePoints(s).length;

/** unicodedata.normalize('NFKC', s); characters CPython considers unassigned pass through. */
export function nfkc(s: string): string {
  let out = "", seg = "";
  for (const cp of codePoints(s)) {
    if (isUnassigned(cp)) {
      out += seg.normalize("NFKC") + String.fromCodePoint(cp);
      seg = "";
    } else seg += String.fromCodePoint(cp);
  }
  return out + seg.normalize("NFKC");
}

export const casefold = (s: string) => codePoints(s).map((cp) => CASEFOLD.get(cp) ?? String.fromCodePoint(cp)).join("");

/** str.lower(), including CPython's Final_Sigma rule for U+03A3 (handle_capital_sigma). */
export function pyLower(s: string): string {
  const cps = codePoints(s);
  const ignorable = (cp: number) => inRanges(T.case_ignorable, cp);
  const cased = (cp: number) => inRanges(T.cased, cp);
  return cps.map((cp, i) => {
    if (cp !== 0x3a3) return LOWER.get(cp) ?? String.fromCodePoint(cp);
    let j = i - 1;
    while (j >= 0 && ignorable(cps[j])) j--;
    let final = j >= 0 && cased(cps[j]);
    if (final) {
      j = i + 1;
      while (j < cps.length && ignorable(cps[j])) j++;
      final = j === cps.length || !cased(cps[j]);
    }
    return final ? "\u03c2" : "\u03c3";
  }).join("");
}

/** str.split() with no arguments. */
export function pySplit(s: string): string[] {
  const out: string[] = [];
  let cur: number[] = [];
  for (const cp of codePoints(s)) {
    if (SPACE.has(cp)) {
      if (cur.length) out.push(fromCps(cur));
      cur = [];
    } else cur.push(cp);
  }
  if (cur.length) out.push(fromCps(cur));
  return out;
}

const LINE_BREAKS = new Set([0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x85, 0x2028, 0x2029]);

/** str.splitlines() without keepends. */
export function pySplitlines(s: string): string[] {
  const cps = codePoints(s), out: string[] = [];
  let start = 0;
  for (let i = 0; i < cps.length; i++) {
    if (!LINE_BREAKS.has(cps[i])) continue;
    out.push(fromCps(cps.slice(start, i)));
    if (cps[i] === 0x0d && cps[i + 1] === 0x0a) i++;
    start = i + 1;
  }
  if (start < cps.length) out.push(fromCps(cps.slice(start)));
  return out;
}

function decimalValue(cp: number): number | null {
  for (const [a, b, v] of T.decimal) if (cp >= a && cp <= b) return v + cp - a;
  return null;
}

/** str.isdigit() of one code point. */
export const pyIsDigit = (cp: number) => inRanges(T.digit, cp);

/**
 * int(s) for a str in base 10: Unicode decimal digits and whitespace, one optional sign, single
 * underscores between digits, at most 4300 digits.
 */
export function pyInt(s: string): bigint {
  let ascii = "";
  for (const cp of codePoints(s)) {
    // Only non-ASCII characters are transformed; ASCII \x1c-\x1f stay and are not int() whitespace.
    if (cp < 0x80) ascii += String.fromCodePoint(cp);
    else if (SPACE.has(cp)) ascii += " ";
    else ascii += decimalValue(cp) ?? "?";
  }
  const m = /^[ \t\n\v\f\r]*([+-]?)([0-9](?:_?[0-9])*)[ \t\n\v\f\r]*$/.exec(ascii);
  if (!m) throw new PyError("ValueError", `invalid literal for int() with base 10: ${reprStr(s)}`);
  const digits = m[2].replaceAll("_", "");
  if (digits.length > 4300) throw new PyError("ValueError", "Exceeds the limit (4300 digits) for integer string conversion");
  return BigInt(m[1] + digits);
}

/** str.upper(), exact only where the result is ASCII letters (enough to compare with ASCII names). */
export const pyUpperAscii = (s: string) => codePoints(s).map((cp) => T.upper_ascii[cp] ?? String.fromCodePoint(cp)).join("");

const cls = (cps: [number, number][]) => cps.map(([a, b]) => (a === b ? `\\u{${a.toString(16)}}` : `\\u{${a.toString(16)}}-\\u{${b.toString(16)}}`)).join("");
/** Body of a /u character class matching re's \w for str patterns. */
export const PY_WORD_CLASS = cls(T.word);
/** Body of a /u character class matching what an ASCII letter matches under re.IGNORECASE. */
export const pyIgnoreCaseClass = (letter: string) => cls((T.ignorecase_ascii[letter.toLowerCase()] ?? [letter.codePointAt(0)!]).map((c) => [c, c]));

/** str.strip() with no arguments. */
export function pyStrip(s: string): string {
  const cps = codePoints(s);
  let a = 0, b = cps.length;
  while (a < b && SPACE.has(cps[a])) a++;
  while (b > a && SPACE.has(cps[b - 1])) b--;
  return fromCps(cps.slice(a, b));
}

const hex = (n: number, width: number) => n.toString(16).padStart(width, "0");

function reprStr(s: string): string {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  for (const cp of codePoints(s)) {
    const ch = String.fromCodePoint(cp);
    if (ch === quote || ch === "\\") out += "\\" + ch;
    else if (cp === 9) out += "\\t";
    else if (cp === 10) out += "\\n";
    else if (cp === 13) out += "\\r";
    else if (cp < 0x20 || cp === 0x7f) out += "\\x" + hex(cp, 2);
    else if (cp < 0x7f || isPrintable(cp)) out += ch;
    else if (cp <= 0xff) out += "\\x" + hex(cp, 2);
    else if (cp <= 0xffff) out += "\\u" + hex(cp, 4);
    else out += "\\U" + hex(cp, 8);
  }
  return out + quote;
}

export function pyRepr(v: PyValue): string {
  if (v === null) return "None";
  if (typeof v === "boolean") return v ? "True" : "False";
  if (typeof v === "bigint") return v.toString();
  if (typeof v === "number") return floatRepr(v);
  if (typeof v === "string") return reprStr(v);
  if (Array.isArray(v)) return "[" + v.map(pyRepr).join(", ") + "]";
  if (isDict(v)) return "{" + [...v].map(([k, x]) => reprStr(k) + ": " + pyRepr(x)).join(", ") + "}";
  throw new Error("unreachable");
}

/** str(value) */
export const pyStr = (v: PyValue) => (typeof v === "string" ? v : pyRepr(v));

/** discovery.rules.text: ' '.join(unicodedata.normalize('NFKC', str(value or '')).casefold().split()) */
export function text(v: PyValue | undefined): string {
  const s = truthy(v) ? pyStr(v!) : "";
  return pySplit(casefold(nfkc(s))).join(" ");
}

/** str.isascii() */
export const isAscii = (s: string) => /^[\x00-\x7f]*$/.test(s);
